import time
import unittest


def classify_workload(func, *args, samples=3):
    wall_best = 0.0
    cpu_best = 0.0
    for _ in range(samples):
        cpu_before = time.process_time()
        wall_before = time.perf_counter()
        func(*args)
        wall = time.perf_counter() - wall_before
        cpu = time.process_time() - cpu_before
        wall_best = max(wall_best, wall)
        cpu_best = max(cpu_best, cpu)
    kind = "cpu-bound" if wall_best > 0 and cpu_best / wall_best >= 0.5 else "io-bound"
    return {"wall": wall_best, "cpu": cpu_best, "kind": kind}


def spin(rounds=200_000):
    total = 0
    for index in range(rounds):
        total += index * index
    return total


def nap(seconds=0.05):
    time.sleep(seconds)


class ClassifyWorkloadTest(unittest.TestCase):
    def test_cpu_bound_spin_is_classified(self):
        result = classify_workload(spin, samples=1)
        self.assertEqual(result["kind"], "cpu-bound")
        self.assertGreaterEqual(result["cpu"], 0.0)
        self.assertGreaterEqual(result["wall"], result["cpu"] * 0.9)

    def test_io_bound_nap_is_classified(self):
        result = classify_workload(nap, 0.05, samples=1)
        self.assertEqual(result["kind"], "io-bound")
        self.assertGreater(result["wall"], 0.04)
        self.assertLess(result["cpu"], 0.05)

    def test_samples_runs_multiple_times(self):
        calls = []

        def counted():
            calls.append(1)

        classify_workload(counted, samples=3)
        self.assertEqual(len(calls), 3)


