import threading
import time
import unittest
from concurrent.futures import ThreadPoolExecutor


def run_serial(workload, items):
    started = time.perf_counter()
    results = [workload(item) for item in items]
    return {"results": results, "wall": time.perf_counter() - started}


def run_threaded(workload, items, max_workers=3):
    started = time.perf_counter()
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        results = list(executor.map(workload, items))
    return {"results": results, "wall": time.perf_counter() - started}


def nap(seconds):
    time.sleep(seconds)
    return round(seconds, 3)


def spin(rounds):
    total = 0
    for index in range(rounds):
        total += index * index
    return total


class CompareModelsTest(unittest.TestCase):
    def test_io_workload_overlaps_in_threads(self):
        items = [0.05, 0.05, 0.05]
        serial = run_serial(nap, items)
        threaded = run_threaded(nap, items)
        self.assertEqual(sorted(threaded["results"]), sorted(serial["results"]))
        self.assertLess(threaded["wall"], serial["wall"] * 0.8)

    def test_cpu_workload_results_match_without_speed_claim(self):
        items = [50_000, 60_000, 70_000]
        serial = run_serial(spin, items)
        threaded = run_threaded(spin, items)
        self.assertEqual(threaded["results"], serial["results"])
        self.assertEqual(len(threaded["results"]), len(items))

    def test_no_threads_survive_the_threaded_run(self):
        before = {thread.ident for thread in threading.enumerate()}
        run_threaded(nap, [0.01, 0.01])
        after = {thread.ident for thread in threading.enumerate()}
        self.assertEqual(after - before, set())


