import unittest


def explain_atomic(statement):
    instructions = [
        instruction.opname
        for instruction in dis.get_instructions(compile(statement, "<s>", "exec"))
        if instruction.opname not in ("RESUME", "CACHE")
    ]
    return {"instructions": instructions, "count": len(instructions)}


class AtomicityTest(unittest.TestCase):
    def setUp(self):
        self.saved = sys.getswitchinterval()

    def tearDown(self):
        sys.setswitchinterval(self.saved)

    def test_single_assignment_is_the_baseline(self):
        self.assertGreaterEqual(explain_atomic("x = 1")["count"], 1)

    def test_read_modify_write_needs_more_instructions(self):
        baseline = explain_atomic("x = 1")["count"]
        self.assertGreater(explain_atomic("x = x + 1")["count"], baseline)
        self.assertGreater(explain_atomic("items = items + [x]")["count"], baseline)

    def test_instructions_are_named(self):
        names = explain_atomic("x = x + 1")["instructions"]
        self.assertTrue(all(isinstance(name, str) and name for name in names))

    def test_switch_interval_round_trips(self):
