import threading
import time
import unittest


def run_with_deadline(target, timeout):
    box = {"result": None, "error": None}

    def runner():
        try:
            box["result"] = target()
        except BaseException as exc:  # 线程里未捕获异常不会传到主线程，必须自己接住
            box["error"] = exc

    thread = threading.Thread(target=runner)
    thread.start()
    thread.join(timeout=timeout)
    status = "done" if not thread.is_alive() else "timeout"
    return {"status": status, "alive": thread.is_alive(), "result": box["result"], "error": box["error"]}


class RunWithDeadlineTest(unittest.TestCase):
    def test_finishes_before_deadline(self):
        outcome = run_with_deadline(lambda: 6 * 7, timeout=2.0)
        self.assertEqual(outcome["status"], "done")
        self.assertFalse(outcome["alive"])
        self.assertEqual(outcome["result"], 42)

    def test_times_out_and_reports_alive(self):
        def slow():
            time.sleep(0.3)

        outcome = run_with_deadline(slow, timeout=0.01)
        self.assertEqual(outcome["status"], "timeout")
        self.assertTrue(outcome["alive"])
        self.assertIsNone(outcome["result"])

    def test_worker_exception_is_returned(self):
        def boom():
            raise ValueError("bad input")

        outcome = run_with_deadline(boom, timeout=2.0)
        self.assertEqual(outcome["status"], "done")
        self.assertIsInstance(outcome["error"], ValueError)
        self.assertEqual(str(outcome["error"]), "bad input")

    def test_thread_object_cannot_restart(self):
        thread = threading.Thread(target=lambda: None)
        thread.start()
        thread.join(timeout=2.0)
        with self.assertRaises(RuntimeError):
            thread.start()

    def test_no_threads_left_alive_eventually(self):
        baseline = threading.active_count()
        run_with_deadline(lambda: time.sleep(0.2), timeout=0.01)  # 故意留下一条慢线程
        deadline = time.perf_counter() + 2.0
        while threading.active_count() > baseline and time.perf_counter() < deadline:
            time.sleep(0.01)
        self.assertEqual(threading.active_count(), baseline)


