import queue
import threading
import unittest


class StoppableWorker:
    def __init__(self):
        self.queue = queue.Queue()
        self.processed = []
        self.thread = threading.Thread(target=self.run, name="stoppable", daemon=False)
        self._stopped = False

    def start(self):
        self.thread.start()

    def submit(self, item):
        self.queue.put(item)

    def stop(self, timeout=2.0):
        self.queue.put(None)
        self.thread.join(timeout=timeout)
        return not self.thread.is_alive()

    def run(self):
        while True:
            item = self.queue.get(timeout=2.0)
            try:
                if item is None:
                    self._stopped = True
                    return
                self.processed.append(item * 2)
            finally:
                self.queue.task_done()

    def is_running(self):
        return self.thread.is_alive()


class StoppableWorkerTest(unittest.TestCase):
    def test_processes_items_in_order_then_stops(self):
        worker = StoppableWorker()
        worker.start()
        for item in (1, 2, 3):
            worker.submit(item)
        self.assertTrue(worker.stop())
        self.assertFalse(worker.is_running())
        self.assertEqual(worker.processed, [2, 4, 6])

    def test_stop_is_idempotent(self):
        worker = StoppableWorker()
        worker.start()
        self.assertTrue(worker.stop())
        self.assertTrue(worker.stop())
        self.assertFalse(worker.is_running())

    def test_worker_is_not_daemon(self):
        worker = StoppableWorker()
        self.assertFalse(worker.thread.daemon)


