import hashlib
import os
import tempfile
import threading
import unittest
from concurrent.futures import ThreadPoolExecutor


def digest_file(path):
    with open(path, "rb") as handle:
        return hashlib.sha256(handle.read()).hexdigest()


def map_files(paths, digest=digest_file, max_workers=3):
    results = {}
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        futures = {path: executor.submit(digest, path) for path in paths}
        for path, future in futures.items():
            try:
                results[path] = future.result(timeout=5.0)
            except OSError as exc:
                results[path] = exc
    return results


class MapFilesTest(unittest.TestCase):
    def setUp(self):
        self.root = tempfile.mkdtemp()
        self.paths = []
        for index, text in enumerate((b"alpha", b"", b"gamma")):
            path = os.path.join(self.root, f"f{index}.txt")
            with open(path, "wb") as handle:
                handle.write(text)
            self.paths.append(path)

    def test_every_path_is_mapped_to_its_own_digest(self):
        results = map_files(self.paths)
        self.assertEqual(set(results), set(self.paths))
        for path in self.paths:
            with open(path, "rb") as handle:
                self.assertEqual(results[path], hashlib.sha256(handle.read()).hexdigest())

    def test_shuffled_input_gives_identical_mapping(self):
        first = map_files(self.paths)
        second = map_files(list(reversed(self.paths)))
        self.assertEqual(first, second)

    def test_missing_path_is_isolated(self):
        missing = os.path.join(self.root, "nope.txt")
        results = map_files(self.paths + [missing])
        self.assertIsInstance(results[missing], OSError)
        self.assertNotIsInstance(results[self.paths[0]], OSError)
        self.assertEqual(results[self.paths[0]], map_files([self.paths[0]])[self.paths[0]])

    def test_no_thread_survives(self):
        before = {thread.ident for thread in threading.enumerate()}
        map_files(self.paths)
        after = {thread.ident for thread in threading.enumerate()}
        self.assertEqual(after - before, set())


