import threading
import time
import unittest
from concurrent.futures import ThreadPoolExecutor, TimeoutError as FutureTimeout


def collect(tasks, max_workers=3):
    ok = {}
    failed = {}
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        futures = {key: executor.submit(func) for key, func in tasks}
        for key, future in futures.items():
            try:
                ok[key] = future.result(timeout=1.0)
            except FutureTimeout as exc:
                failed[key] = exc
            except Exception as exc:  # worker 的原始异常在这里被转成数据
                failed[key] = exc
    return {"ok": ok, "failed": failed}


class CollectTest(unittest.TestCase):
    def test_all_succeed(self):
        outcome = collect([("a", lambda: 1), ("b", lambda: 2)])
        self.assertEqual(outcome["ok"], {"a": 1, "b": 2})
        self.assertEqual(outcome["failed"], {})

    def test_failure_is_isolated(self):
        def boom():
            raise ValueError("cannot parse bad")

        outcome = collect([("a", lambda: 1), ("bad", boom), ("c", lambda: 3)])
        self.assertEqual(outcome["ok"], {"a": 1, "c": 3})
        self.assertIsInstance(outcome["failed"]["bad"], ValueError)
        self.assertEqual(str(outcome["failed"]["bad"]), "cannot parse bad")

    def test_slow_task_is_reported_as_timeout(self):
        outcome = collect([("slow", lambda: time.sleep(1.5)), ("fast", lambda: 1)])
        self.assertIsInstance(outcome["failed"]["slow"], FutureTimeout)
        self.assertEqual(outcome["ok"]["fast"], 1)

    def test_no_threads_left_behind(self):
        before = {thread.ident for thread in threading.enumerate()}
        collect([("a", lambda: 1)])
        after = {thread.ident for thread in threading.enumerate()}
        self.assertEqual(after - before, set())


