import threading
import time
import unittest
from concurrent.futures import ThreadPoolExecutor, TimeoutError as FutureTimeout
from concurrent.futures import as_completed


def first_wins(tasks, deadline):
    order = []
    with ThreadPoolExecutor(max_workers=max(1, min(4, len(tasks)))) as executor:
        futures = {executor.submit(time.sleep, seconds): key for key, seconds in tasks}
        try:
            for future in as_completed(futures, timeout=deadline):
                order.append(futures[future])
        except FutureTimeout:
            pass
        pending = [key for future, key in futures.items() if not future.done()]
        for future in futures:
            if not future.done():
                future.cancel()
        for future in futures:
            if future.done() and not future.cancelled():
                future.result(timeout=1.0)
    return {"order": order, "pending": sorted(pending)}


class FirstWinsTest(unittest.TestCase):
    def test_shortest_task_finishes_first(self):
        outcome = first_wins([("slow", 0.2), ("fast", 0.02)], deadline=2.0)
        self.assertEqual(outcome["order"][0], "fast")
        self.assertEqual(outcome["pending"], [])
        self.assertEqual(sorted(outcome["order"]), ["fast", "slow"])

    def test_deadline_leaves_pending_keys(self):
        outcome = first_wins([("slow", 0.3), ("fast", 0.02)], deadline=0.1)
        self.assertIn("fast", outcome["order"])
        self.assertIn("slow", outcome["pending"])
        self.assertEqual(set(outcome["order"]) & set(outcome["pending"]), set())

    def test_order_uses_keys_from_input(self):
        tasks = [("a", 0.05), ("b", 0.01), ("c", 0.02)]
        outcome = first_wins(tasks, deadline=2.0)
        self.assertEqual(outcome["order"][0], "b")
        self.assertEqual(set(outcome["order"]), {"a", "b", "c"})

    def test_no_threads_left_behind(self):
        before = {thread.ident for thread in threading.enumerate()}
        first_wins([("a", 0.01)], deadline=2.0)
        after = {thread.ident for thread in threading.enumerate()}
        self.assertEqual(after - before, set())


