import threading
import unittest
from concurrent.futures import Future, ThreadPoolExecutor


class SerialExecutor:
    def submit(self, func, *args):
        future = Future()
        try:
            future.set_result(func(*args))
        except Exception as exc:
            future.set_exception(exc)
        return future

    def map(self, func, iterable):
        return [self.submit(func, item).result(timeout=0.1) for item in iterable]

    def __enter__(self):
        return self

    def __exit__(self, *exc_info):
        return False


class PoolExecutor:
    def __init__(self, max_workers=2):
        self.pool = ThreadPoolExecutor(max_workers=max_workers)

    def submit(self, func, *args):
        return self.pool.submit(func, *args)

    def map(self, func, iterable):
        return list(self.pool.map(func, iterable))

    def __enter__(self):
        return self

    def __exit__(self, *exc_info):
        self.pool.shutdown(wait=True)
        return False


def double(value):
    return value * 2


def boom(value):
    raise ValueError("cannot double " + str(value))


class ExecutorParityTest(unittest.TestCase):
    def test_serial_future_is_done_immediately(self):
        with SerialExecutor() as executor:
            future = executor.submit(double, 3)
            self.assertTrue(future.done())
            self.assertEqual(future.result(timeout=0.1), 6)

    def test_both_executors_map_the_same(self):
        with SerialExecutor() as serial, PoolExecutor() as pool:
            self.assertEqual(serial.map(double, [1, 2, 3]), pool.map(double, [1, 2, 3]))
            self.assertEqual(pool.map(double, [1, 2, 3]), [2, 4, 6])

    def test_failures_are_exposed_as_exceptions(self):
        with SerialExecutor() as serial, PoolExecutor() as pool:
            serial_future = serial.submit(boom, 1)
            pool_future = pool.submit(boom, 1)
            self.assertIsInstance(serial_future.exception(timeout=0.1), ValueError)
            self.assertIsInstance(pool_future.exception(timeout=2.0), ValueError)

    def test_no_threads_after_pool_exit(self):
        before = {thread.ident for thread in threading.enumerate()}
        with PoolExecutor() as pool:
            pool.map(double, [1, 2])
        after = {thread.ident for thread in threading.enumerate()}
        self.assertEqual(after - before, set())


