import queue
import threading
import unittest


def run_pipeline(items, maxsize=2, workers=2, timeout=5.0):
    work = queue.Queue(maxsize=maxsize)
    results = []
    lock = threading.Lock()

    def consume():
        while True:
            item = work.get(timeout=timeout)
            try:
                if item is None:
                    return
                with lock:
                    results.append(item * 2)
            finally:
                work.task_done()

    consumers = [threading.Thread(target=consume) for _ in range(workers)]
    for thread in consumers:
        thread.start()
    for item in items:
        work.put(item, timeout=timeout)
    for _ in consumers:
        work.put(None, timeout=timeout)
    for thread in consumers:
        thread.join(timeout=timeout)
    work.join()
    return {"results": sorted(results), "queue_empty": work.empty(),
            "alive": any(thread.is_alive() for thread in consumers)}


class PipelineTest(unittest.TestCase):
    def test_results_are_complete(self):
        outcome = run_pipeline(range(1, 11))
        self.assertEqual(outcome["results"], [value * 2 for value in range(1, 11)])
        self.assertTrue(outcome["queue_empty"])
        self.assertFalse(outcome["alive"])

    def test_single_slot_queue_still_finishes(self):
        outcome = run_pipeline(range(1, 6), maxsize=1, workers=2)
        self.assertEqual(outcome["results"], [2, 4, 6, 8, 10])
