import queue
import threading
import unittest


class WorkerPool:
    def __init__(self, handler, workers=2, maxsize=0):
        self.handler = handler
        self.work = queue.Queue(maxsize=maxsize)
        self.processed = 0
        self.failed = []
        self.lock = threading.Lock()
        self.threads = [threading.Thread(target=self._run) for _ in range(workers)]
        self._closed = False

    def start(self):
        for thread in self.threads:
            thread.start()
        return self

    def submit(self, item, timeout=2.0):
        self.work.put(item, timeout=timeout)

    def _run(self):
        while True:
            item = self.work.get(timeout=5.0)
            try:
                if item is None:
                    return
                try:
                    self.handler(item)
                except Exception as exc:
                    with self.lock:
                        self.failed.append((item, exc))
                else:
                    with self.lock:
                        self.processed += 1
            finally:
                self.work.task_done()

    def shutdown(self, timeout=5.0):
        if not self._closed:
            self._closed = True
            for _ in self.threads:
                self.work.put(None, timeout=timeout)
        for thread in self.threads:
            thread.join(timeout=timeout)
        self.work.join()
        stopped = all(not thread.is_alive() for thread in self.threads)
        return {"processed": self.processed, "failed": list(self.failed), "stopped": stopped}


class WorkerPoolTest(unittest.TestCase):
    def test_all_tasks_processed_then_stop(self):
        seen = []
        pool = WorkerPool(seen.append, workers=3).start()
        for item in range(6):
            pool.submit(item)
        report = pool.shutdown()
        self.assertTrue(report["stopped"])
        self.assertEqual(report["processed"], 6)
        self.assertEqual(sorted(seen), list(range(6)))
        self.assertEqual(report["failed"], [])
        self.assertTrue(pool.work.empty())
        self.assertEqual(pool.work.qsize(), 0)

    def test_handler_failure_is_collected(self):
        def handler(item):
            if item == "bad":
                raise ValueError("bad item")

        pool = WorkerPool(handler, workers=2).start()
        for item in ("ok", "bad", "also-ok"):
            pool.submit(item)
        report = pool.shutdown()
        self.assertEqual(report["processed"], 2)
        self.assertEqual([item for item, _ in report["failed"]], ["bad"])
        self.assertIsInstance(report["failed"][0][1], ValueError)

    def test_shutdown_is_idempotent(self):
        pool = WorkerPool(lambda item: None, workers=2).start()
        pool.submit(1)
        first = pool.shutdown()
        second = pool.shutdown()
        self.assertEqual(first["processed"], 1)
        self.assertEqual(second["processed"], 1)
        self.assertTrue(second["stopped"])


