import queue
import threading
import unittest


def try_put(work, item, timeout=0.1):
    try:
        work.put(item, timeout=timeout)
    except queue.Full:
        return False
    return True


def drain(work, max_items, timeout=0.1):
    items = []
    empty_seen = False
    while len(items) < max_items:
        try:
            items.append(work.get(timeout=timeout))
        except queue.Empty:
            empty_seen = True
            break
    return {"items": items, "empty_seen": empty_seen}


class QueueBoundaryTest(unittest.TestCase):
    def test_try_put_reports_full(self):
        work = queue.Queue(maxsize=1)
        self.assertTrue(try_put(work, "first"))
        self.assertFalse(try_put(work, "second"))
        self.assertEqual(work.qsize(), 1)

    def test_drain_reports_empty(self):
        work = queue.Queue()
        outcome = drain(work, max_items=3, timeout=0.05)
        self.assertTrue(outcome["empty_seen"])
        self.assertEqual(outcome["items"], [])

    def test_drain_stops_at_max_items(self):
        work = queue.Queue()
        for value in range(5):
            work.put(value)
        outcome = drain(work, max_items=2, timeout=0.05)
        self.assertEqual(outcome["items"], [0, 1])
        self.assertFalse(outcome["empty_seen"])
        self.assertEqual(work.qsize(), 3)

    def test_try_put_succeeds_when_consumer_drains(self):
        work = queue.Queue(maxsize=1)
        self.assertTrue(try_put(work, 1))
        picked = []

