import threading
import time
import unittest


def run_when_ready(target, dependencies, timeout=1.0):
    ready = threading.Event()
    lock = threading.Lock()
    completed = []
    remaining = [len(dependencies)]
    threads = []

    def runner(name, func):
        try:
            func()
        finally:
            with lock:
                completed.append(name)
                remaining[0] -= 1
                if remaining[0] == 0:
                    ready.set()

    for name, func in dependencies:
        thread = threading.Thread(target=runner, args=(name, func))
        thread.start()
        threads.append(thread)
    signalled = ready.wait(timeout=timeout)
    if signalled:
        target()
    for thread in threads:
        thread.join(timeout=timeout)
    return {"completed": sorted(completed), "timed_out": not signalled,
            "elapsed_under_limit": all(not thread.is_alive() for thread in threads)}


class RunWhenReadyTest(unittest.TestCase):
    def test_all_dependencies_then_target(self):
        calls = []
        outcome = run_when_ready(
            lambda: calls.append("target"),
            [("fast", lambda: None), ("also-fast", lambda: None)],
            timeout=1.0,
        )
        self.assertFalse(outcome["timed_out"])
        self.assertEqual(outcome["completed"], ["also-fast", "fast"])
        self.assertEqual(calls, ["target"])
        self.assertTrue(outcome["elapsed_under_limit"])

    def test_slow_dependency_times_out_and_skips_target(self):
        calls = []

        def slow():
            time.sleep(0.3)

        outcome = run_when_ready(lambda: calls.append("target"), [("slow", slow)], timeout=0.05)
        self.assertTrue(outcome["timed_out"])
        self.assertEqual(calls, [])

    def test_no_threads_left_behind(self):
        before = {thread.ident for thread in threading.enumerate()}
        run_when_ready(lambda: None, [("only", lambda: None)], timeout=1.0)
        after = {thread.ident for thread in threading.enumerate()}
