import unittest


def run_rounds(worker, workers=3, rounds=3, timeout=1.0, parties=None):
    barrier = threading.Barrier(parties or workers)
    slots = [None] * workers
    collected = []
    lock = threading.Lock()
    broken = []

    def run(slot):
        for round_index in range(rounds):
            try:
                barrier.wait(timeout=timeout)
            except threading.BrokenBarrierError:
                with lock:
                    broken.append(slot)
                return
            slots[slot] = worker(slot, round_index)
            try:
                barrier.wait(timeout=timeout)
            except threading.BrokenBarrierError:
                with lock:
                    broken.append(slot)
                return
            if slot == 0:
                with lock:
                    collected.append(list(slots))

    threads = [threading.Thread(target=run, args=(slot,)) for slot in range(workers)]
    for thread in threads:
        thread.start()
    for thread in threads:
        thread.join(timeout=timeout * rounds * 2 + 1)
    return {"rounds": collected, "broken": bool(broken),
            "alive": any(thread.is_alive() for thread in threads)}


