import threading
import unittest
from concurrent.futures import ThreadPoolExecutor


def run_limited(tasks, limit=2, max_workers=4):
    gate = threading.Semaphore(limit)
    lock = threading.Lock()
    active = 0
    peak = 0
    ok = {}
    failed = {}

    def worker(key, func):
        nonlocal active, peak
        with gate:
            with lock:
                active += 1
                peak = max(peak, active)
            try:
                return key, func(), None
            except Exception as exc:
                return key, None, exc
            finally:
                with lock:
                    active -= 1

    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        futures = [executor.submit(worker, key, func) for key, func in tasks]
        for future in futures:
            key, value, error = future.result(timeout=5.0)
            if error is None:
                ok[key] = value
            else:
                failed[key] = (type(error).__name__, str(error))

    permits = sum(1 for _ in range(limit) if gate.acquire(blocking=False))
    for _ in range(permits):
        gate.release()
    return {"ok": ok, "failed": failed, "peak": peak, "limit_respected": peak <= limit,
            "permits_free": permits == limit}


class RunLimitedTest(unittest.TestCase):
    def test_peak_respects_the_limit(self):
        tasks = [("k" + str(index), (lambda: index)) for index in range(6)]
        outcome = run_limited(tasks, limit=2)
        self.assertTrue(outcome["limit_respected"])
        self.assertLessEqual(outcome["peak"], 2)
        self.assertEqual(len(outcome["ok"]), 6)

    def test_failures_carry_context(self):
        def boom():
            raise ValueError("bad payload")

        outcome = run_limited([("good", lambda: 1), ("bad", boom)], limit=1)
        self.assertEqual(outcome["ok"], {"good": 1})
        self.assertEqual(outcome["failed"]["bad"], ("ValueError", "bad payload"))

    def test_permits_are_released_after_failures(self):
        def boom():
            raise RuntimeError("nope")

        outcome = run_limited([("a", boom), ("b", boom)], limit=2)
        self.assertTrue(outcome["permits_free"])
        self.assertEqual(set(outcome["failed"]), {"a", "b"})

    def test_no_threads_left_behind(self):
        before = {thread.ident for thread in threading.enumerate()}
        run_limited([("a", lambda: 1)], limit=1)
        after = {thread.ident for thread in threading.enumerate()}
        self.assertEqual(after - before, set())


