from concurrent.futures import ThreadPoolExecutor, as_completed


def compute(item, fail_on=()):
    if item in fail_on:
        raise ValueError("bad item")
    time.sleep(0.005 * (4 - item))
    return item * 10


def build_report(items, mode="ordered", max_workers=3, fail_on=()):
    pairs = []
    failures = 0
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        futures = {item: executor.submit(compute, item, fail_on) for item in items}
        if mode == "ordered":
            order = [(item, futures[item]) for item in items]
        else:
            owner = {future: item for item, future in futures.items()}
            order = [(owner[future], future) for future in as_completed(futures.values())]
        for key, future in order:
            try:
                pairs.append((key, future.result(timeout=5.0)))
            except Exception as exc:
                failures += 1
                pairs.append((key, type(exc).__name__))
    values = [value for _, value in pairs if isinstance(value, int)]
    return {"items": pairs, "summary": {"count": len(pairs), "total": sum(values), "failed": failures}}


