import threading
import time
import unittest
from concurrent.futures import ThreadPoolExecutor, TimeoutError as FutureTimeout


class ManagedExecutor:
    def __init__(self, max_workers=2):
        self.pool = ThreadPoolExecutor(max_workers=max_workers)
        self.closed = False
        self.submitted = []

    def submit(self, func, *args):
        if self.closed:
            raise RuntimeError("executor is closed")
        future = self.pool.submit(func, *args)
        self.submitted.append(future)
        return future

    def close(self, cancel_pending=False, timeout=5.0):
        if self.closed:
            return {"closed": True, "cancelled": 0}
        self.closed = True
        cancelled = 0
        if cancel_pending:
            for future in self.submitted:
                if not future.done() and future.cancel():
                    cancelled += 1
        self.pool.shutdown(wait=True)
        return {"closed": True, "cancelled": cancelled}

    def __enter__(self):
        return self

    def __exit__(self, *exc_info):
        self.close()
        return False


def wait_for(future, timeout):
    try:
        return "done", future.result(timeout=timeout)
    except FutureTimeout:
        return "timeout", None


class ManagedExecutorTest(unittest.TestCase):
    def test_close_then_submit_is_rejected(self):
        executor = ManagedExecutor(max_workers=1)
        self.assertEqual(executor.close(), {"closed": True, "cancelled": 0})
        with self.assertRaises(RuntimeError):
            executor.submit(lambda: 1)
        self.assertEqual(executor.close(), {"closed": True, "cancelled": 0})

    def test_cancel_pending_keeps_running_task(self):
        executor = ManagedExecutor(max_workers=1)
        running = executor.submit(time.sleep, 0.05)
        queued = executor.submit(time.sleep, 0.05)
        report = executor.close(cancel_pending=True)
        self.assertIsInstance(report["cancelled"], int)
        self.assertTrue(running.done())
        self.assertTrue(queued.cancelled())

    def test_wait_for_timeout_and_done(self):
        executor = ManagedExecutor(max_workers=2)
        with executor:
            self.assertEqual(wait_for(executor.submit(time.sleep, 0.2), timeout=0.01), ("timeout", None))
            self.assertEqual(wait_for(executor.submit(lambda: 7), timeout=2.0), ("done", 7))

    def test_error_path_still_closes(self):
        executor = ManagedExecutor(max_workers=1)
        with self.assertRaises(ValueError):
            with executor:
                executor.submit(time.sleep, 0.01)
                raise ValueError("setup failed")
        self.assertTrue(executor.closed)
        with self.assertRaises(RuntimeError):
            executor.submit(lambda: 1)

    def test_no_threads_left_behind(self):
        before = {thread.ident for thread in threading.enumerate()}
        with ManagedExecutor(max_workers=2) as executor:
            executor.submit(time.sleep, 0.01)
        after = {thread.ident for thread in threading.enumerate()}
        self.assertEqual(after - before, set())


