import threading
import time
import unittest
from contextlib import contextmanager


class ConcurrencyGuard:
    def __init__(self):
        self.lock = threading.Lock()
        self.active = 0
        self.peak = 0
        self.failures = 0
        self.started = time.perf_counter()

    @contextmanager
    def guard_section(self):
        with self.lock:
            self.active += 1
            self.peak = max(self.peak, self.active)
        try:
            yield
        finally:
            with self.lock:
                self.active -= 1

    def record_failure(self, exc):
        with self.lock:
            self.failures += 1

    def report(self):
        with self.lock:
            return {"peak": self.peak, "failures": self.failures,
                    "elapsed": time.perf_counter() - self.started}


def wait_until(predicate, timeout, condition=None):
    condition = condition or threading.Condition()
    with condition:
        return condition.wait_for(predicate, timeout=timeout)


class ConcurrencyGuardTest(unittest.TestCase):
    def test_peak_tracks_concurrent_sections(self):
        guard = ConcurrencyGuard()

        def work():
            with guard.guard_section():
                time.sleep(0.02)

        threads = [threading.Thread(target=work) for _ in range(3)]
        for thread in threads:
            thread.start()
        for thread in threads:
            thread.join(timeout=2.0)
        report = guard.report()
        self.assertEqual(report["peak"], 3)
        self.assertEqual(guard.active, 0)
        self.assertFalse(any(thread.is_alive() for thread in threads))

    def test_failures_are_counted(self):
        guard = ConcurrencyGuard()
        guard.record_failure(ValueError("one"))
        guard.record_failure(RuntimeError("two"))
        self.assertEqual(guard.report()["failures"], 2)
        self.assertIn("elapsed", guard.report())

    def test_wait_until_detects_ready_state(self):
        state = {"ready": False}

        def flag():
            state["ready"] = True

        thread = threading.Thread(target=flag)
        thread.start()
        self.assertTrue(wait_until(lambda: state["ready"], timeout=2.0))
        thread.join(timeout=2.0)

    def test_wait_until_times_out(self):
        started = time.perf_counter()
        self.assertFalse(wait_until(lambda: False, timeout=0.05))
        self.assertLess(time.perf_counter() - started, 1.0)


