import time
import unittest
from concurrent.futures import ProcessPoolExecutor, TimeoutError as FutureTimeout


def quick(value):
    return value * 2


def slow(seconds):
    time.sleep(seconds)
    return seconds


def run_with_recovery(tasks, per_task_timeout=0.2, max_workers=1):
    ok = {}
    timed_out = []
    rebuilt = 0
    executor = ProcessPoolExecutor(max_workers=max_workers)
    try:
        for key, func, args in tasks:
            future = executor.submit(func, *args)
            try:
                ok[key] = future.result(timeout=per_task_timeout)
            except FutureTimeout:
                timed_out.append(key)
                executor.shutdown(wait=False, cancel_futures=True)
                executor = ProcessPoolExecutor(max_workers=max_workers)
                rebuilt += 1
    finally:
        executor.shutdown(wait=False, cancel_futures=True)
    return {"ok": ok, "timed_out": timed_out, "rebuilt": rebuilt}


class RecoveryTest(unittest.TestCase):
    def test_all_quick_tasks_succeed(self):
        outcome = run_with_recovery([("a", quick, (1,)), ("b", quick, (2,))])
        self.assertEqual(outcome["ok"], {"a": 2, "b": 4})
        self.assertEqual(outcome["timed_out"], [])
        self.assertEqual(outcome["rebuilt"], 0)

    def test_timeout_is_isolated_and_pool_is_rebuilt(self):
        tasks = [("slow", slow, (5,)), ("fast", quick, (3,))]
        started = time.perf_counter()
        outcome = run_with_recovery(tasks, per_task_timeout=0.2, max_workers=1)
        elapsed = time.perf_counter() - started
        self.assertIn("slow", outcome["timed_out"])
        self.assertEqual(outcome["ok"]["fast"], 6)
        self.assertGreaterEqual(outcome["rebuilt"], 1)
        self.assertLess(elapsed, 4.0)

    def test_source_has_main_guard(self):
        with open(__file__, encoding="utf-8") as handle:
            self.assertIn("if __name__ == \"__main__\":", handle.read())


if __name__ == "__main__":
    unittest.main()
